import { useCallback, useState } from 'react';
import { Button, Input } from '@jinx-ui/react';

type RegistrationData = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY_DATA: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const REVIEW_LABELS: Array<[keyof RegistrationData, string]> = [
  ['name', 'Имя'],
  ['email', 'Email'],
  ['phone', 'Телефон'],
  ['country', 'Страна'],
  ['city', 'Город'],
  ['street', 'Улица, дом'],
  ['zip', 'Индекс'],
];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY_DATA);

  const isLast = step === STEPS.length - 1;

  const update = useCallback(
    (field: keyof RegistrationData) => (event: React.ChangeEvent<HTMLInputElement>) => {
      const { value } = event.target;
      setData((prev) => ({ ...prev, [field]: value }));
    },
    [],
  );

  const goBack = useCallback(() => setStep((prev) => Math.max(0, prev - 1)), []);
  const goNext = useCallback(
    () => setStep((prev) => Math.min(STEPS.length - 1, prev + 1)),
    [],
  );

  const handleSubmit = useCallback(
    (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      if (isLast) {
        onSubmit(data);
      } else {
        goNext();
      }
    },
    [data, goNext, isLast, onSubmit],
  );

  return (
    <form className="jx-card jx-stack" onSubmit={handleSubmit} noValidate>
      <ol
        className="jx-steps"
        style={{ display: 'flex', gap: 'var(--jx-space-3)', listStyle: 'none', margin: 0, padding: 0 }}
      >
        {STEPS.map((label, index) => (
          <li
            key={label}
            className="jx-step"
            aria-current={index === step ? 'step' : undefined}
            data-state={index === step ? 'active' : index < step ? 'done' : 'todo'}
            style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-2)' }}
          >
            <span className="jx-badge">{index + 1}</span>
            <span className="jx-step-label">{label}</span>
          </li>
        ))}
      </ol>

      <h2 className="jx-heading">{STEPS[step]}</h2>

      {step === 0 && (
        <div className="jx-stack" style={{ display: 'grid', gap: 'var(--jx-space-3)' }}>
          <label className="jx-field">
            <span className="jx-label">Имя</span>
            <Input name="name" value={data.name} onChange={update('name')} autoComplete="name" />
          </label>
          <label className="jx-field">
            <span className="jx-label">Email</span>
            <Input
              name="email"
              type="email"
              value={data.email}
              onChange={update('email')}
              autoComplete="email"
            />
          </label>
          <label className="jx-field">
            <span className="jx-label">Телефон</span>
            <Input
              name="phone"
              type="tel"
              value={data.phone}
              onChange={update('phone')}
              autoComplete="tel"
            />
          </label>
        </div>
      )}

      {step === 1 && (
        <div className="jx-stack" style={{ display: 'grid', gap: 'var(--jx-space-3)' }}>
          <label className="jx-field">
            <span className="jx-label">Страна</span>
            <Input
              name="country"
              value={data.country}
              onChange={update('country')}
              autoComplete="country-name"
            />
          </label>
          <label className="jx-field">
            <span className="jx-label">Город</span>
            <Input
              name="city"
              value={data.city}
              onChange={update('city')}
              autoComplete="address-level2"
            />
          </label>
          <label className="jx-field">
            <span className="jx-label">Улица, дом</span>
            <Input
              name="street"
              value={data.street}
              onChange={update('street')}
              autoComplete="street-address"
            />
          </label>
          <label className="jx-field">
            <span className="jx-label">Индекс</span>
            <Input
              name="zip"
              value={data.zip}
              onChange={update('zip')}
              autoComplete="postal-code"
            />
          </label>
        </div>
      )}

      {step === 2 && (
        <dl
          className="jx-list"
          style={{ display: 'grid', gap: 'var(--jx-space-2)', margin: 0 }}
        >
          {REVIEW_LABELS.map(([field, label]) => (
            <div
              key={field}
              className="jx-list-row"
              style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-3)' }}
            >
              <dt className="jx-label">{label}</dt>
              <dd className="jx-value" style={{ margin: 0 }}>
                {data[field] || '—'}
              </dd>
            </div>
          ))}
        </dl>
      )}

      <div
        className="jx-actions"
        style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-3)' }}
      >
        <Button type="button" variant="secondary" onClick={goBack} disabled={step === 0}>
          Назад
        </Button>
        <Button type="submit" variant="primary">
          {isLast ? 'Отправить' : 'Дальше'}
        </Button>
      </div>
    </form>
  );
}

